// The inbox department: triage, draft, edit, package.
let email = input()
let reply = ""

// Decide what deserves attention first.
if email feels "needs a reply urgently" with confidence 80% {
  print("Priority: reply soon. The inbox has developed opinions.")
} otherwise maybe {
  print("Priority: unclear. Check the deadline yourself.")
} else {
  print("Priority: normal. Finish your coffee.")
}

// Same input, different jobs for the LLM.
match email {
  "an invitation to speak or participate in an event" => {
    reply = llm "Draft a brief reply expressing interest, without accepting. Ask for missing event details. Do not invent availability, a talk title or a signature." using email
  }
  "a routine request to schedule a meeting" => {
    reply = llm "Draft a short scheduling reply. Ask for two possible times if none were offered; otherwise acknowledge the options and say availability needs checking. Do not pick a time or invent availability. No signature." using email
  }
  "an unsolicited sales pitch" => {
    reply = llm "Politely decline in one sentence. No invented excuses, no promises to reconnect, no signature." using email
  }
  "another kind of message" => {
    reply = llm "Draft a warm acknowledgement and a useful clarifying question. Do not invent answers, commitments or a signature. Keep it short." using email
  }
}

// Revise until the draft sounds like a person.
while reply feels "stiff, corporate, or unnecessarily wordy" {
  reply = llm "Make this brief and natural. Preserve its meaning and questions. Add no new facts or commitments." using reply
}

// A last check can admit uncertainty.
if reply feels "polite and clear about the next step" with confidence 80% {
  print("Review: ready for you to read.")
} otherwise maybe {
  print("Review: the editor is unsure. Give this a closer look.")
} else {
  reply = llm "Make this polite and give it one clear next step. Preserve facts; make no commitments." using reply
  print("Review: revised once more. Check the final wording.")
}

// Generate a subject from the finished reply, not the first draft.
let subject = llm "Write a reply subject line, at most 7 words. No quotes, labels or commentary." using reply
print("Subject:")
print(subject)
print("Draft reply:")
print(reply)

// Turn a corporate announcement into human speech.
let draft = input()

// Jev picks the description that fits best.
match draft {
  "a corporate announcement" => {
    print("An exciting development in saying things.")
  }
  "a sales pitch" => {
    print("Someone would like our money.")
  }
  "a normal human message" => {
    print("A promising start.")
  }
}

// Rewrite, then ask Jev again. Stop when the jargon is gone.
while draft feels "full of corporate jargon" {
  draft = llm "Rewrite plainly in one short sentence." using draft
}

// Uncertainty gets its own branch.
if draft feels "clear and specific" with confidence 80% {
  print("Approved for human consumption.")
} otherwise maybe {
  print("Understandable? Probably. Ask a human.")
} else {
  print("We have successfully produced different nonsense.")
}

// Print the finished draft.
print(draft)

let message = input()

if message feels "genuinely urgent" with confidence 80% {
  print("Okay. This is a drop-everything situation.")
} otherwise maybe {
  print("Define urgent. And define tiny favor.")
} else {
  print("This could have been an email. Oh, it is.")
}

let draft = input()

while draft feels "like a LinkedIn influencer post" {
  draft = llm "Rewrite this as a normal person. Remove corporate language, humblebrags and life lessons. One short sentence." using draft
}

print("We have achieved human speech. Probably.")
print(draft)

let feedback = input()

match feedback {
  "a useful suggestion" => {
    print("Added to the roadmap. A mythical place.")
  }
  "a bug report" => {
    print("That is, regrettably, our department.")
  }
  "someone having a day" => {
    print("We hear you. We are also having a day.")
  }
}

let pitch = llm "Pitch this startup in two enthusiastic sentences." using input()
print(pitch)

chaos {
  if pitch feels "a financially responsible business idea" {
    print("We are raising a seed round.")
  } else {
    print("We are raising a seed round anyway.")
  }
}

// This one runs without any model calls.
let greeting = "Hello, uncertainty."
print(greeting)

repeat 3 {
  print("Everything is going according to some plan.")
}
